recipes.code:
{
  "inputs": [
    {
      "id": "cloudmindmaps-api-key",
      "type": "promptString",
      "description": "Your CloudMindMaps API key. Generate one while signed in at https://cloudmindmaps.app (see the MCP setup guide).",
      "password": true
    }
  ],
  "servers": {
    "mindmaps": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "cloudmindmaps-mcp@1.1.0"
      ],
      "env": {
        "CLOUDMINDMAPS_API_KEY": "${input:cloudmindmaps-api-key}",
        "CLOUDMINDMAPS_API_URL": "https://cloudmindmaps.app"
      }
    }
  }
}
